#!/bin/bash
read -p "Enter two numbers: " num1 num2
read -p "Enter operation to perform (AND, OR, NOT): " op
case $op in
  AND) echo "Result: $num1 & $num2 = $((num1&num2))" ;;
  OR) echo "Result: $num1 | $num2 = $((num1|num2))" ;;
  NOT) echo "Result: $num1 ^ $num2 = $((num1^num2))" ;;
  *) echo "Invalid operator." ;;
esac

#!/bin/bash
read -p "Enter two values (true/false): " val1 val2
read -p "Enter an operation (and/or/not): " op
case $op in
  and)
    if [[ $val1 == true && $val2 == true ]]; then echo "Result: true"; else echo "Result: false"; fi ;;
  or)
    if [[ $val1 == true || $val2 == true ]]; then echo "Result: true"; else echo "Result: false"; fi ;;
  not)
    if [[ $val1 == true ]]; then echo "Result: false"; else echo "Result: true"; fi ;;
  *) echo "Invalid operator." ;;
esac

