#!/bin/bash
read -p "Enter source directory: " source_dir
read -p "Enter destination directory: " dest_dir
mkdir -p "${dest_dir}/Documents" "${dest_dir}/Images" "${dest_dir}/Music" "${dest_dir}/Videos" "${dest_dir}/Others"
for file in "${source_dir}"/*; do
  if [ -f "${file}" ]; then
    extension="${file##*.}"
    case "${extension}" in
      txt|pdf|doc|docx) mv "${file}" "${dest_dir}/Documents" ;;
      jpg|jpeg|png|gif) mv "${file}" "${dest_dir}/Images" ;;
      mp3|wav) mv "${file}" "${dest_dir}/Music" ;;
      mp4|avi|mkv) mv "${file}" "${dest_dir}/Videos" ;;
      *) mv "${file}" "${dest_dir}/Others" ;;
    esac
  fi
done
echo "Files organized successfully!"
